     3	import { EmploymentStatus } from '../../shared/types/index';
     4	import { Employee } from './employee.model';
     5	import { IEmployeeRepository } from './employee.repository.interface';
     6	import { CreateEmployeeDto, IEmployeeService } from './employee.service.interface';
     7	
     8	export class EmployeeService implements IEmployeeService {
     9	  constructor(private readonly repo: IEmployeeRepository) {}
    10	
    11	  async getById(id: string): Promise<Employee | null> {
    12	    return this.repo.findById(id);
    13	  }
    14	
    15	  async getByEmployeeNumber(employeeNumber: string): Promise<Employee | null> {
    16	    return this.repo.findByEmployeeNumber(employeeNumber);
    17	  }
    18	
    19	  async getSubordinates(managerId: string): Promise<Employee[]> {
    20	    return this.repo.findByManagerId(managerId);
    21	  }
    22	
    23	  async create(data: CreateEmployeeDto): Promise<Employee> {
    24	    const now = new Date();
    25	    const employee: Employee = {
    26	      id: crypto.randomUUID(),
    27	      employeeNumber: data.employeeNumber,
    28	      firstName: data.firstName,
    29	      lastName: data.lastName,
    30	      email: data.email,
    31	      managerId: data.managerId ?? null,
    32	      department: data.department,
    33	      hireDate: data.hireDate,
    34	      terminationDate: null,
    35	      employmentStatus: EmploymentStatus.ACTIVE,
    36	      createdAt: now,
    37	      updatedAt: now,
    38	      deletedAt: null,
    39	    };
    40	    return this.repo.create(employee);
    41	  }
    42	
    43	  async update(id: string, data: Partial<Employee>): Promise<Employee | null> {
    44	    const allowedFields: (keyof Employee)[] = [
    45	      'firstName',
    46	      'lastName',
    47	      'email',
    48	      'managerId',
    49	      'department',
    50	      'hireDate',
    51	    ];
    52	    const sanitized: Partial<Employee> = {};
    53	    for (const key of allowedFields) {
    54	      if (key in data) {
    55	        (sanitized as Record<string, unknown>)[key] = (data as Record<string, unknown>)[key];
    56	      }
    57	    }
    58	    return this.repo.update(id, sanitized);
    59	  }
    60	
    61	  async terminate(id: string): Promise<Employee | null> {
    62	    const existing = await this.repo.findById(id);
    63	    if (!existing) {
    64	      return null;
    65	    }
    66	    return this.repo.update(id, {
    67	      employmentStatus: EmploymentStatus.TERMINATED,
    68	      terminationDate: new Date(),
    69	    });
    70	  }
    71	}
