     1	import { FastifyReply, FastifyRequest } from 'fastify';
     2	
     3	import { IEmployeeService } from './employee.service.interface';
     4	
     5	export function makeEmployeeController(service: IEmployeeService) {
     6	  return {
     7	    getEmployeeById: async (request: FastifyRequest, reply: FastifyReply) => {
     8	      const { id } = request.params as { id: string };
     9	      const employee = await service.getById(id);
    10	      if (!employee) {
    11	        return reply.status(404).send({ error: 'Employee not found' });
    12	      }
    13	      return reply.status(200).send(employee);
    14	    },
    15	
    16	    getEmployeeByNumber: async (request: FastifyRequest, reply: FastifyReply) => {
    17	      const { employeeNumber } = request.params as { employeeNumber: string };
    18	      const employee = await service.getByEmployeeNumber(employeeNumber);
    19	      if (!employee) {
    20	        return reply.status(404).send({ error: 'Employee not found' });
    21	      }
    22	      return reply.status(200).send(employee);
    23	    },
    24	
    25	    getSubordinates: async (request: FastifyRequest, reply: FastifyReply) => {
    26	      const { managerId } = request.params as { managerId: string };
    27	      const subordinates = await service.getSubordinates(managerId);
    28	      return reply.status(200).send(subordinates);
    29	    },
    30	
    31	    createEmployee: async (request: FastifyRequest, reply: FastifyReply) => {
    32	      const data = request.body as Record<string, unknown>;
    33	      const employee = await service.create({
    34	        employeeNumber: data.employeeNumber as string,
    35	        firstName: data.firstName as string,
    36	        lastName: data.lastName as string,
    37	        email: data.email as string,
    38	        managerId: data.managerId as string | null | undefined,
    39	        department: data.department as string,
    40	        hireDate: new Date(data.hireDate as string),
    41	      });
    42	      return reply.status(201).send(employee);
    43	    },
    44	
    45	    updateEmployee: async (request: FastifyRequest, reply: FastifyReply) => {
    46	      const { id } = request.params as { id: string };
    47	      const data = request.body as Record<string, unknown>;
    48	      const employee = await service.update(id, data);
    49	      if (!employee) {
    50	        return reply.status(404).send({ error: 'Employee not found' });
    51	      }
    52	      return reply.status(200).send(employee);
    53	    },
    54	
    55	    terminateEmployee: async (request: FastifyRequest, reply: FastifyReply) => {
    56	      const { id } = request.params as { id: string };
    57	      const employee = await service.terminate(id);
    58	      if (!employee) {
    59	        return reply.status(404).send({ error: 'Employee not found' });
    60	      }
    61	      return reply.status(200).send(employee);
    62	    },
    63	  };
    64	}
