     1	import { FastifyInstance } from 'fastify';
     2	
     3	import { makeEmployeeController } from './employee.controller';
     4	import { EmployeeService } from './employee.service';
     5	import { IEmployeeRepository } from './employee.repository.interface';
     6	
     7	export async function employeeRoutes(
     8	  fastify: FastifyInstance,
     9	  repo: IEmployeeRepository,
    10	): Promise<void> {
    11	  const service = new EmployeeService(repo);
    12	  const controller = makeEmployeeController(service);
    13	
    14	  fastify.get('/employees/number/:employeeNumber', controller.getEmployeeByNumber);
    15	  fastify.get('/employees/:id', controller.getEmployeeById);
    16	  fastify.get('/employees/:managerId/subordinates', controller.getSubordinates);
    17	  fastify.post('/employees', controller.createEmployee);
    18	  fastify.put('/employees/:id', controller.updateEmployee);
    19	  fastify.post('/employees/:id/terminate', controller.terminateEmployee);
    20	}
